<script lang="ts">import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import Status from '$lib/components/Status.svelte';import NewMailbox from '$lib/components/mail/NewMailbox.svelte';import DnsSetup from '$lib/components/mail/DnsSetup.svelte';import Forwarders from '$lib/components/mail/Forwarders.svelte';import WebmailLink from '$lib/components/mail/WebmailLink.svelte';import {mailState,mailDomains,mailReady,mailStorageError} from '$lib/mail/store';import {address,messagesFor,usage} from '$lib/mail/model.js';import {workspace} from '$lib/stores/workspace';let tab='Mailboxes',query='',filter='',create=false,notice='';$: domains=mailDomains($mailState,$workspace.domains);$: rows=$mailState.mailboxes.filter(m=>(!filter||m.domain===filter)&&address(m).includes(query.toLowerCase().trim()));</script>
<Heading title="Email" subtitle="Create business email addresses and manage mail delivery.">{#if tab==='Mailboxes'}<button class="btn primary" disabled={!$mailReady||!!$mailStorageError} on:click={()=>create=!create}><Icon name="Plus"/>Create mailbox</button>{/if}</Heading><div class="tabs native-tabs">{#each ['Mailboxes','Forwarders','DNS & setup'] as t}<button class="tab" class:active={tab===t} on:click={()=>{tab=t;create=false;notice='';}}>{t}</button>{/each}</div>{#if !$mailReady}<p class="subtitle">Loading sample mailboxes…</p>{:else if $mailStorageError}<div class="callout" role="alert">{$mailStorageError}</div>{:else if tab==='Forwarders'}<Forwarders {domains}/>{:else if tab==='DNS & setup'}<DnsSetup {domains}/>{:else}<div class="stack">{#if create}<NewMailbox {domains} onSaved={()=>{create=false;notice='Sample mailbox created. Password was not stored.';}} onCancel={()=>create=false}/>{/if}{#if notice}<p class="subtitle" role="status">{notice}</p>{/if}<section class="card table-card"><div class="table-head"><div class="toolbar"><label class="search"><Icon name="Search"/><input bind:value={query} placeholder="Search mailboxes" aria-label="Search mailboxes"/></label><div class="row wrap"><span class="count">{rows.length} mailboxes</span><select class="input" bind:value={filter} aria-label="Filter by domain"><option value="">All domains</option>{#each domains as d}<option>{d}</option>{/each}</select></div></div></div><div class="table-wrap"><table class="mail-table"><thead><tr><th>Email address</th><th>Storage used</th><th>Status</th><th></th></tr></thead><tbody>{#each rows as m (m.id)}<tr><td><div class="row"><span class="icon-box"><Icon name="Email"/></span><div><a class="link-btn mail-address" href={'/email/'+m.id}>{address(m)}</a><small>{m.label||'Mailbox'}</small></div></div></td><td><div class="mail-quota"><span>{(usage(messagesFor($mailState,m.id))/1024).toFixed(1)} KB / {m.quota} GB</span><div class="mail-meter"><i style={'width:'+Math.min(100,usage(messagesFor($mailState,m.id))/(m.quota*1024**3)*100)+'%'}></i></div></div></td><td><Status value={m.suspended?'Suspended':$mailState.dns[m.domain]?'Configured (demo)':'DNS pending'}/></td><td><div class="table-actions"><WebmailLink mailbox={m}/><a class="btn secondary small" href={'/email/'+m.id}>Manage</a></div></td></tr>{:else}<tr><td colspan="4">No mailboxes found. Create an email address or change your filters.</td></tr>{/each}</tbody></table></div></section><small>Mailboxes are independent of websites. Mail delivery is simulated.</small></div>{/if}
